//! Golden corpus for the `w3lib.html.replace_entities` port.
//!
//! `testdata/w3lib_entities.jsonl` was generated by running w3lib's algorithm under
//! CPython 3.14 (with the real `html.entities.name2codepoint` table and the real
//! `cp1252` codec) over a hand-picked set of inputs covering every branch: named,
//! decimal and hexadecimal references; terminated and unterminated; known and unknown;
//! the cp1252 `0x80..=0x9F` remap including its five undefined bytes; out-of-range and
//! overflowing numerics; `keep`; and `remove_illegal=False`.
//!
//! `ARCHITECTURE.md` §6 makes this a required gate: every off-the-shelf Rust HTML
//! decoder differs from w3lib on four separate points, so drift here is silent.

use std::fs;
use std::path::PathBuf;

use browser_core::entities::{replace_entities, replace_entities_with};
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    input: String,
    expected: String,
    #[serde(default = "default_true")]
    remove_illegal: bool,
    #[serde(default)]
    keep: Vec<String>,
}

fn default_true() -> bool {
    true
}

fn corpus_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/w3lib_entities.jsonl")
}

#[test]
fn matches_w3lib_on_every_golden_case() {
    let path = corpus_path();
    let text =
        fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));

    let mut checked = 0usize;
    for (lineno, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let case: Case = serde_json::from_str(line)
            .unwrap_or_else(|e| panic!("{}:{}: bad JSON: {e}", path.display(), lineno + 1));

        let keep: Vec<&str> = case.keep.iter().map(String::as_str).collect();
        let got = replace_entities_with(&case.input, &keep, case.remove_illegal);
        assert_eq!(
            got,
            case.expected,
            "{}:{}: replace_entities({:?}, keep={:?}, remove_illegal={}) = {:?}, w3lib says {:?}",
            path.display(),
            lineno + 1,
            case.input,
            case.keep,
            case.remove_illegal,
            got,
            case.expected,
        );

        // The convenience wrapper must agree with the full form on the defaults.
        if case.remove_illegal && case.keep.is_empty() {
            assert_eq!(replace_entities(&case.input), case.expected);
        }
        checked += 1;
    }

    assert!(
        checked >= 90,
        "the golden corpus shrank to {checked} cases; it should cover every branch"
    );
}
